"""Deterministic CI-only test fixture; NOT generated by the local AI."""

def normalize_status(value):
    """Normalize explicitly supported status aliases; fail closed otherwise."""
    if not isinstance(value, str):
        return "HOLD"
    value = value.strip().lower()
    if value in {"pass", "passed", "ok", "done", "success"}:
        return "PASS"
    if value in {"fail", "failed", "error"}:
        return "FAIL"
    return "HOLD"
